/* =======================================================
   PUBMED OVERRIDES
   ======================================================= */

:root {
  --pubmed-blue: #2b5f97;
  --pubmed-blue-dark: #1f4e80;
  --pubmed-link: #0056b3;
  --pubmed-border: #d6dbe1;
  --pubmed-muted: #5f6b7a;
  --pubmed-bg: #f4f7fb;
  --pubmed-serif: "Times New Roman", "Songti SC", serif;
  --pubmed-sans: "Arial", "Helvetica Neue", "PingFang SC", sans-serif;
  --paper-title: "A Multicenter Review of Conversational Artifacts in AI Settings";
  --paper-meta: "Review > SillyTavern. 2026 May 18:S0114-000(26)00514-0.\A doi: 10.1000/S0114-000(26)00514-0. ";
  --paper-affiliation: "Affiliations: Department of RP Studies, ST Institute\A PMID: 42424242   DOI: 10.1000/S0114-000(26)00514-0.";
}

#bg_custom,
#bg1 {
  background: linear-gradient(180deg, #edf2f8 0%, #f9fbfd 100%) !important;
}

#top-settings-holder {
  top: 0;
  background: var(--pubmed-blue) !important;
  border-bottom: 0 !important;
  box-shadow: none !important;
  padding: 0 10px !important;
}

#top-settings-holder .drawer {
  background: transparent !important;
  color: #fff !important;
}

#top-settings-holder .drawer-icon::before {
  display: none !important;
}

#top-settings-holder .drawer-icon {
  opacity: 1 !important;
  width: auto !important;
  min-width: 10px;
  height: 44px !important;
  margin: 0 2px !important;
  padding: 0 2px !important;
  display: flex !important;
  align-items: center;
  justify-content: center;
  background: transparent !important;
}

#top-settings-holder .drawer-icon::after {
  color: #fff !important;
  font-family: var(--pubmed-sans);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: none;
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon.openIcon {
  color: #fff !important;
  background: rgba(255, 255, 255, 0.12) !important;
  -webkit-background-clip: border-box;
  background-clip: border-box;
  border-radius: 2px;
}

#top-settings-holder .drawer-icon:hover::after,
#top-settings-holder .drawer-icon.openIcon::after {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.drawer-icon.fa-sliders::after { content: "AI"; }
.drawer-icon.fa-plug::after { content: "API"; }
.drawer-icon.fa-font::after { content: "Format"; }
.drawer-icon.fa-book-atlas::after { content: "World"; }
.drawer-icon.fa-user::after { content: "Theme"; }
.drawer-icon.fa-image::after { content: "Image"; }
.drawer-icon.fa-cubes::after { content: "Tool"; }
.drawer-icon.fa-bars-progress::after { content: "Table"; }
.drawer-icon.fa-face-smile::after { content: "User"; }
.drawer-icon.fa-address-card::after { content: "Char"; }


#sheld {
  top: calc(var(--topBarBlockSize) + 8px);
  padding-top: 8px;
}

#chat {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 8px 0 24px !important;
}

.mes .avatar,
.mesAvatarWrapper {
  display: none !important;
}

/* 核心 PubMed 文章卡片布局 */
.mes[is_user="false"] {
  position: relative !important;
  display: block !important;
  width: min(1120px, calc(100% - 16px)) !important;
  margin: 0 auto 18px !important;
  padding: 0 0 28px !important;
  background: #fff !important;
  border: 1px solid var(--pubmed-border) !important;
  border-top: 0 !important;
  border-radius: 0 !important;
  box-shadow: 0 2px 6px rgba(25, 51, 80, 0.08) !important;
  overflow: visible !important;
}

/* 用提供的官方原图作为整个消息框的顶部题图 */
.mes[is_user="false"]::before {
  content: "";
  display: block !important;
  width: 100%;
  padding-top: 44%; /* 维持原图的完美长宽比例 */
  background: url("https://p.sda1.dev/32/e3d34f2260863675181f93c0a28aab9d/pubmed.png") top center / 100% auto no-repeat;
  background-color: #f4f7fb;
  margin-bottom: 5px;
}

/* 重置所有内部消息块以进行弹性盒子布局重排 */
.mes[is_user="false"] .mes_block {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  padding: 0 !important;
}

/* 隐藏不再需要的左右侧边滑动块 */
.mes[is_user="false"] .swipe_left,
.mes[is_user="false"] .swipeRightBlock {
  display: none !important;
}

/* --- 核心文章信息重排区域 --- */
.mes[is_user="false"] .ch_name {
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  padding: 0 40px !important;
  margin: 0 !important;
  box-sizing: border-box;
}

/* 强制内部的 Flex Container 竖向且严格左对齐 */
.mes[is_user="false"] .ch_name .flex-container,
.mes[is_user="false"] .ch_name .alignItemsBaseline {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;
  text-align: left !important;
  width: 100%;
}

/* 1. Meta / Review 数据块 (最上方，左对齐) */
.mes[is_user="false"] .timestamp {
  order: 1;
  display: block !important;
  position: static !important;
  width: 100% !important;
  margin: 0 0 15px 0 !important;
  padding: 0 !important;
  background: transparent !important;
  color: transparent !important;
  font-size: 0 !important;
  text-align: left !important;
}

.mes[is_user="false"] .timestamp::before {
  content: var(--paper-meta);
  display: block;
  white-space: pre-wrap;
  font-family: var(--pubmed-sans);
  font-size: 14px;
  line-height: 1.4;
  color: var(--pubmed-muted);
  text-align: left !important;
}

/* 2. 论文大标题 (在Meta之后，左对齐) */
.mes[is_user="false"] .timestamp::after {
  content: var(--paper-title);
  display: block;
  margin-top: 10px;
  font-family: var(--pubmed-serif);
  font-size: clamp(20px, 3.5vw, 28px);
  line-height: 1.1;
  font-weight: 700;
  color: #000000;
  text-align: left !important;
}

/* 3. 动态角色名字作为论文第一作者 */
.mes[is_user="false"] .name_text {
  order: 2;
  display: block !important;
  width: 100% !important;
  font-family: var(--pubmed-sans) !important;
  font-size: 14px !important;
  line-height: 1.1 !important;
  color: var(--pubmed-link) !important;
  font-weight: 400 !important;
  text-decoration: none !important;
  margin: 0 0 10px 0 !important;
  text-align: left !important;
}

/* 虚拟联合作者 */
.mes[is_user="false"] .name_text::after {
  content: " ¹ , SillyTavern² ";
  color: var(--pubmed-link);
}

/* 4. Affiliation 归属机构与PMID (利用原生隐形的 ghost 图标接管) */
.mes[is_user="false"] .mes_ghost {
  order: 3;
  display: block !important;
  visibility: visible !important;
  width: 100%;
  font-style: normal;
  margin: 0 0 14px 0 !important;
  text-align: left !important;
}

.mes[is_user="false"] .mes_ghost::before {
  content: var(--paper-affiliation) !important;
  display: block;
  white-space: pre-wrap;
  font-family: var(--pubmed-sans);
  font-size: 14px;
  line-height: 1.6;
  font-weight: 400;
  color: #15171a;
  text-transform: none;
  text-align: left !important;
}

/* 5. 嵌入 cite.png：与 Review / 标题 / 作者 / Affiliation / PMID 左边缘严格对齐 */
.mes[is_user="false"] .ch_name::before {
  content: "";
  order: 4;
  display: block !important;
  position: static !important;
  align-self: flex-start !important;
  box-sizing: border-box !important;
  width: 100% !important;
  height: auto !important;
  margin-left: -40px;
  padding-top: 6%;
  background: url("https://p.sda1.dev/32/30f8a130eb02332c41d0f4035eea3c36/cite.png") left center / 100% 100% no-repeat !important;

}

/* 6. Abstract 标题：让原生消息按钮位于其下方 */
.mes[is_user="false"] .ch_name::after {
  content: "Abstract" !important;
  order: 5;
  display: block !important;
  position: static !important;
  left: auto !important;
  bottom: auto !important;
  width: 100% !important;
  height: auto !important;
  margin: 36px 0 18px;
  background: transparent !important;
  font-family: var(--pubmed-serif);
  font-size: 24px;
  font-weight: 700;
  line-height: 1.1;
  color: #15171a;
  text-align: left !important;
}

/* 隐藏无关小挂件：保留 SillyTavern 原生 .mes_buttons / .mes_edit_buttons */
.mes[is_user="false"] .mesIDDisplay,
.mes[is_user="false"] .mes_timer,
.mes[is_user="false"] .tokenCounterDisplay,
.mes[is_user="false"] .mes_reasoning_header {
  display: none !important;
}

/* 原生消息按钮：位于 Abstract 标题下方，避免滚轮/裁切，不重写按钮外观 */
.mes[is_user="false"] .mes_buttons,
.mes[is_user="false"] .mes_edit_buttons {
  order: 6;
  position: static !important;
  align-self: flex-start !important;
  width: auto !important;
  max-width: 100% !important;
  max-height: none !important;
  height: auto !important;
  margin: 0 0 18px 0 !important;
  padding: 0 !important;
  overflow: visible !important;
  overscroll-behavior: auto !important;
  flex-wrap: wrap !important;
}

.mes[is_user="false"] .extraMesButtons {
  max-height: none !important;
  height: auto !important;
  overflow: visible !important;
  flex-wrap: wrap !important;
}

/* --- Abstract 正文部分 --- */
.mes[is_user="false"] .mes_text {
  width: 100% !important;
  padding: 0 40px 0 !important;
  margin: 0 !important;
  color: #1f2429 !important;
}

.mes[is_user="false"] .mes_text::before {
  content: none !important;
}

.mes[is_user="false"] .mes_text,
.mes[is_user="false"] .mes_text p,
.mes[is_user="false"] .mes_text li {
  font-family: var(--pubmed-sans);
  font-size: 16px !important;
  line-height: 1.4 !important;
  color: #1f2429 !important;
}

.mes[is_user="false"] .mes_text p {
  margin-bottom: 14px;
}

.mes[is_user="false"] .mes_text h1 {
  font-size: 24px !important;
  color: #15171a !important;
}

.mes[is_user="false"] .mes_text h2 {
  font-size: 20px !important;
  color: #15171a !important;
}

.mes[is_user="false"] .mes_text h3 {
  font-size: 18px !important;
  color: #15171a !important;
}

.mes[is_user="false"] .mes_text a,
.mes[is_user="false"] .name_text a {
  color: var(--pubmed-link) !important;
}

.mes[is_user="false"] .mes_text strong {
  color: #000000 !important;
  font-weight: 700 !important;
}

.mes[is_user="false"] .mes_text del {
  color: #7b8490 !important;
}


.mes[is_user="false"] .mes_text hr {
  border: none !important;
  border-top: 1px solid #d6dbe1 !important;
  margin: 24px 0 !important;
}

.mes[is_user="false"] .mes_text table {
  font-size: 15px !important;
  color: #1f2429 !important;
  border-collapse: collapse !important;
}

.mes[is_user="false"] .mes_text th,
.mes[is_user="false"] .mes_text td {
  border: 1px solid #d6dbe1 !important;
  padding: 8px 10px !important;
}

.mes[is_user="false"] .mes_text th {
  background: #f1f3f5 !important;
  color: #15171a !important;
  font-weight: 700 !important;
}

/* 用户对话框模拟简洁白底框 */
.mes[is_user="true"] {
  width: min(1120px, calc(100% - 16px)) !important;
  margin: 0 auto 18px !important;
  border: 1px solid #d7dde5 !important;
  background: #fbfcfe !important;
}

.mes[is_user="true"] .mes_block {
  width: 100% !important;
}

.mes[is_user="true"] .mes_text {
  padding: 16px 24px 20px !important;
}

.mes[is_user="true"] .ch_name::after {
  display: none !important;
}

body.no-blur #send_form,
#send_form {
  background: #ffffff !important;
  border: 1px solid var(--pubmed-border) !important;
  border-radius: 0 !important;
  padding: 0 10px !important;
}

@media screen and (max-width: 760px) {
  .mes[is_user="false"] .ch_name,
  .mes[is_user="false"] .mes_text {
    padding-left: 18px !important;
    padding-right: 18px !important;
  }
  .mes[is_user="false"] .timestamp::after {
    font-size: 30px;
  }
}
